12	declare_rule! {
13	    /// Disallow initializing variables to `undefined`.
14	    ///
15	    /// A variable that is declared and not initialized to any value automatically gets the value of `undefined`.
16	    /// It’s considered a best practice to avoid initializing variables to `undefined`.
17	    /// Please note that any inline comments attached to the initialization value or variable will be removed on auto-fix.
18	    /// Please be also aware that this differs from Eslint's behaviour and we are still discussing on how to properly handle this case.
19	    ///
20	    /// ## Examples
21	    ///
22	    /// ### Invalid
23	    ///
24	    /// ```js,expect_diagnostic
25	    /// var a = undefined;
26	    /// ```
27	    /// ```js,expect_diagnostic
28	    /// let b = undefined, c = 1, d = 2;
29	    /// ```
30	    /// ```js,expect_diagnostic
31	    /// for (let i = 0; i < 100; i++) {
32	    /// 	let i = undefined;
33	    /// }
34	    /// ```
35	    /// ```js,expect_diagnostic
36	    /// let f = /**/undefined/**/ ;
37	    /// ```
38	    /// ### Valid
39	    ///
40	    /// ```js
41	    /// var a = 1;
42	    /// ```
43	    /// ```js
44	    /// class Foo {
45	    /// 	bar = undefined;
46	    /// }
47	    /// ```
48	    ///
49	    pub NoUselessUndefinedInitialization {
50	        version: "1.7.2",
51	        name: "noUselessUndefinedInitialization",
52	        sources: &[RuleSource::Eslint("no-undef-init")],
53	        source_kind: RuleSourceKind::Inspired,
54	        fix_kind: FixKind::Unsafe,
55	        recommended: false,
56	    }
57	}
58	
59	impl Rule for NoUselessUndefinedInitialization {
60	    type Query = Ast<JsVariableDeclaration>;
61	    type State = (String, TextRange);
62	    type Signals = Vec<Self::State>;
63	    type Options = ();
64	
65	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
66	        let node = ctx.query();
67	        let let_or_var_kind = node.is_let() || node.is_var();
68	
69	        let mut signals = vec![];
70	
71	        if !let_or_var_kind {
72	            return signals;
73	        }
74	
75	        for declarator in node.declarators() {
76	            let Ok(decl) = declarator else { continue };
77	
78	            let Some(initializer) = decl.initializer() else {
79	                continue;
80	            };
81	
82	            let Some(keyword) = initializer
83	                .expression()
84	                .ok()
85	                .and_then(|expression| expression.as_js_reference_identifier())
86	            else {
87	                continue;
88	            };
89	
90	            if keyword.is_undefined() {
91	                let decl_range = initializer.range();
92	                let Some(binding_name) = decl.id().ok().map(|id| id.text()) else {
93	                    continue;
94	                };
95	                signals.push((binding_name, decl_range));
96	            }
97	        }
98	
99	        signals
100	    }
101	
102	    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
103	        Some(RuleDiagnostic::new(
104	            rule_category!(),
105	            state.1,
106	            markup! {
107	                "It's not necessary to initialize "<Emphasis>{state.0}</Emphasis>" to undefined."
108	            }).note("A variable that is declared and not initialized to any value automatically gets the value of undefined.")
109	        )
110	    }
111	
112	    fn action(ctx: &RuleContext<Self>, state: &Self::State) -> Option<JsRuleAction> {
113	        let declarators = ctx.query().declarators();
114	
115	        let initializer = declarators
116	            .clone()
117	            .into_iter()
118	            .find(|el| {
119	                el.as_ref()
120	                    .ok()
121	                    .and_then(|element| element.id().ok())
122	                    .is_some_and(|id| id.text() == state.0)
123	            })
124	            .map(|decl| decl.ok())?
125	            .and_then(|declarator| declarator.initializer())?;
126	
127	        let mut mutation = ctx.root().begin();
128	        // This will remove any comments attached to the initialization clause
129	        mutation.remove_node(initializer);
130	
131	        Some(JsRuleAction {
132	            category: ActionCategory::QuickFix,
133	            applicability: Applicability::MaybeIncorrect,
134	            message: markup! { "Remove undefined initialization." }.to_owned(),
135	            mutation,
136	        })
137	    }
138	}
