28	    ///     doSomethingAlways();
29	    /// }
30	    /// ```
31	    ///
32	    /// ```js,expect_diagnostic
33	    /// if (undefined) {
34	    ///     doSomethingUnfinished();
35	    /// }
36	    /// ```
37	    ///
38	    /// ```js,expect_diagnostic
39	    /// for (;-2;) {
40	    ///     doSomethingForever();
41	    /// }
42	    /// ```
43	    ///
44	    /// ```js,expect_diagnostic
45	    /// while (typeof x) {
46	    ///     doSomethingForever();
47	    /// }
48	    /// ```
49	    ///
50	    /// ```js,expect_diagnostic
51	    /// var result = 0 ? a : b;
52	    /// ```
53	    ///
54	    /// ### Valid
55	    ///
56	    /// ```js
57	    /// if (x === 0) {
58	    ///     doSomething();
59	    /// }
60	    ///
61	    /// for (;;) {
62	    ///     doSomethingForever();
63	    /// }
64	    ///
65	    /// while (typeof x === "undefined") {
